import { YIndexedDB } from 'y-json';
import WebSocket from 'ws';

interface Document {
    data: any;
    version: number;
}

class IndexedDBStorage {
    private db: IDBDatabase;

    constructor(dbName: string) {
        this.db = window.indexedDB.open(dbName);
        this.db.onupgradeneeded = () => {
            // Create object store if it doesn't exist
            const transaction = this.db.transaction(['documents'], 'readwrite');
            const objectStore = transaction.objectStore('documents');
            if (!objectStore.keyIndexExists()) {
                objectStore.createKeyIndex({ name: 'version', unique: true });
            }
        };
    }

    async open(): Promise<IDBObjectStore> {
        return this.db.objectStore('documents');
    }

    async insert(doc: Document): Promise<void> {
        const transaction = await this.db.transaction(['documents'], 'readwrite');
        const objectStore = transaction.objectStore('documents');

        let docId = doc.version.toString();
        while (await objectStore.get(docId)) {
            docId += 1;
        }
        await objectStore.put(doc);
    }

    async get(version: number): Promise<Document | undefined> {
        const transaction = await this.db.transaction(['documents']);
        const objectStore = transaction.objectStore('documents');
        const result = await objectStore.get(version);
        return result ? result.data : undefined;
    }
}

